pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item.
    // Lower is better, so we start with the post residual.
    let mut score = post_residual as f64;

    // ------------------------------
    // 1. Strict dead‑space avoidance
    // ------------------------------
    // If the bin cannot accommodate the next item, it will be closed.
    // Penalise such a bin heavily to discourage opening it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;
    } else {
        // Small residuals that can still fit the next item are
        // penalised moderately so we avoid creating tiny gaps.
        score += (post_residual as f64) * 0.2;
    }

    // Penalise bins whose residual is significantly below the mean residual.
    // This discourages leaving many small gaps across open bins.
    let mean_diff = (mean_residual - post_residual as f64).max(0.0);
    score += mean_diff * 0.5;

    // ------------------------------
    // 2. Open‑bin pressure
    // ------------------------------
    // The more open bins we have, the more we prefer to pack tightly.
    // Add a small cost proportional to the amount of space that would remain
    // if we use this bin, scaled by the number of open bins.
    let space_to_fill = (bin_capacity - post_residual) as f64;
    score += (open_bins_count as f64) * space_to_fill * 0.01;

    // ------------------------------
    // 3. Last‑chance fit bonus
    // ------------------------------
    // If this is the only bin that can accommodate the item, give a large
    // negative bonus so it is chosen over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // ------------------------------
    // 4. New‑bin candidate handling
    // ------------------------------
    // When the function is called for a brand‑new empty bin
    // (bin_residual == bin_capacity), we penalise opening a new bin
    // if there exists any open bin that can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Prefer using an existing bin over opening a new one.
            score += 30.0;
        } else {
            // No existing bin can fit – reduce the penalty to allow a new bin.
            score -= 20.0;
        }
    }

    // ------------------------------
    // 5. Stream progression modifier
    // ------------------------------
    // Early in the stream we are stricter about opening new bins,
    // so we add a small penalty that decays as we progress.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placement
    let mut score = post_residual as f64;

    // 1. Dead‑space avoidance: heavily penalise tiny or unusable gaps
    if post_residual < 5 || (next_item_size > 0 && next_item_size > post_residual) {
        score += 100.0;
    }

    // 2. Penalise large items left in too small a gap
    if item_size > 80 && post_residual < 20 {
        score += 30.0;
    }

    // 3. Pressure from many open bins – we want to keep the count low
    score += (open_bins_count as f64) * 1.5;

    // 4. Residual imbalance penalty – prefer residuals close to the mean
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // 5. Reward if this is the only bin that can accommodate the item
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 6. New‑bin candidate penalty – discourage opening a fresh bin unless necessary
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // 7. Progress factor – earlier decisions are less penalised, tightening
    //    as we approach the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // Strict dead‑space avoidance:
    // - Heavy penalty if the remaining gap cannot accommodate the next item.
    // - Extra penalty for very small gaps that are unlikely to be useful.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 1000.0;
    }
    if post_residual < 5 {
        score += 500.0;
    }

    // Open‑bins pressure:
    // The more open bins we have, the more we want to fill them efficiently.
    // Penalize bins whose residual is below the mean residual.
    let open_factor = (open_bins_count as f64).sqrt(); // scaling factor
    let residual_gap = mean_residual - post_residual as f64;
    if residual_gap > 0.0 {
        score += open_factor * residual_gap;
    }

    // New‑bin candidate: penalize opening a brand‑new bin unless forced.
    if bin_residual == bin_capacity {
        score += 200.0;
    }

    // Fitting bins count: if this is the only bin that can fit the item, reward it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: leftover space after placing the item
    let mut score = post_residual as f64;

    // ----- Dead‑space penalty ---------------------------------------------
    // Penalty for leaving a gap that cannot fit the next item
    let mut dead_space_penalty = 0.0;
    if next_item_size > 0 && post_residual < next_item_size {
        dead_space_penalty = (next_item_size as f64 - post_residual as f64) * 10.0;
    }
    // Extra penalty for tiny gaps (< 10 units)
    if post_residual < 10 {
        dead_space_penalty += 50.0;
    }
    score += dead_space_penalty;

    // ----- Open‑bin pressure -----------------------------------------------
    // Prefer using existing bins; discourage opening new ones
    score += (open_bins_count as f64) * 2.0;

    // ----- Sole‑fitting‑bin bonus ------------------------------------------
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // ----- New‑bin candidate penalty ---------------------------------------
    if bin_residual == bin_capacity {
        // Penalise opening a brand‑new bin when we already have many open ones
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 5.0;
        }
    }

    // ----- Residual balance bonus ------------------------------------------
    // Encourage bins whose residual is close to the mean residual
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mean_ratio = mean_residual / bin_capacity as f64;
    score += (residual_ratio - mean_ratio).abs() * 10.0;

    // ----- Progress‑dependent adjustment ------------------------------------
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Near the end, be slightly more tolerant of dead space
        score -= dead_space_penalty * 0.5;
    }

    score
}
